if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }

var elementColors = ['#ffffff', '#2a9d8f', '#00b4d8', '#e63946', '#ffb703'];
var elementNames = ['金', '木', '水', '火', '土'];
var particles = [];
var numParticlesPerElem = 120;

function ElementParticle(elemIdx) {
    this.elemIdx = elemIdx;
    this.colStr = elementColors[elemIdx];
    this.reset();
}
ElementParticle.prototype.reset = function() {
    this.angle = random(TWO_PI);
    this.r = random(180, 280);
    this.z = random(-100, 100);
    this.speed = random(0.01, 0.03);
    this.size = random(3, 8);
};
ElementParticle.prototype.update = function(beat) {
    this.angle += this.speed * (1.0 + beat * 2.0);
    this.r += sin(this.angle * 3) * 0.8;
};
ElementParticle.prototype.draw = function(cx, cy, beat) {
    var x = cx + cos(this.angle + (this.elemIdx * TWO_PI / 5)) * this.r;
    var y = cy + sin(this.angle + (this.elemIdx * TWO_PI / 5)) * this.r;
    noStroke();
    fill(this.colStr);
    circle(x, y, this.size * (1.0 + beat * 0.4));
};

function setup() {
    createCanvas(windowWidth, windowHeight);
    for (var e = 0; e < 5; e++) {
        for (var i = 0; i < numParticlesPerElem; i++) {
            particles.push(new ElementParticle(e));
        }
    }
}

function draw() {
    fill(10, 10, 15, 30);
    rect(0, 0, width, height);

    var beat = (window.beatEnergy || 0.0);
    var low = (window.audioLow || 0.5);
    var cx = width / 2;
    var cy = height / 2;

    push();
    stroke('#ffd700');
    strokeWeight(1.5);
    noFill();
    beginShape();
    for (var i = 0; i < 5; i++) {
        var a = (TWO_PI / 5) * i * 2 - HALF_PI + frameCount * 0.005;
        var px = cx + cos(a) * 220;
        var py = cy + sin(a) * 220;
        vertex(px, py);
    }
    endShape(CLOSE);
    pop();

    for (var i = 0; i < particles.length; i++) {
        var p = particles[i];
        p.update(beat);
        p.draw(cx, cy, beat);
    }

    for (var i = 0; i < 5; i++) {
        var a = (TWO_PI / 5) * i - HALF_PI + frameCount * 0.005;
        var tx = cx + cos(a) * 260;
        var ty = cy + sin(a) * 260;
        fill(elementColors[i]);
        noStroke();
        textSize(24);
        textAlign(CENTER, CENTER);
        text(elementNames[i], tx, ty);
    }
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
